	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		PerformanceMetric
	 */
		public PerformanceMetric createPerformanceMetric( CreatePerformanceMetricCommand command ) {

		PerformanceMetric entity = new PerformanceMetric();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setPerformanceMetricId( command.getPerformanceMetricId() );
            entity.setDate( command.getDate() );
            entity.setValue( command.getValue() );
            entity.setMetricType( command.getMetricType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of PerformanceMetric {0} ", entity.toString() );

		return entity;
	}

